// TH16 v1.00a Stage 1 道中第1波
// 源：st01.ecl.txt MainSub00:1115-1141；子敌 GirlA01:59-85 / GirlA01_at:87-133
const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// 本作 touhou-bullets.ecl：原 type4 / color6
const TH16_BALL: int = 416;

// 源 GirlA01 + GirlA01_at：GirlRedA01/GirlBlueA01 共用行为（外观与掉落已按口径省略）
async sub girl() {
    var shots: int = 2;      // !H 2发 / !LO 5发（A=diffI(1,1,2,5)）
    var gap: int = 20;       // !H 20 / !LO 12
    var delay: int = 20;     // 首发等待 !H 20 / !LO 0
    var bspeed: fx = 3fx;    // etSpeed 首速 !H 3.0f / !LO 4.0f（单层只取首速）
    var back: fx = 12fx;     // ANIM 出生退位移 = 4帧×初速：!H 12px / !LO 16px
    if global(GVAR_RANK) >= RANK_LUNATIC {
        shots = 5;
        gap = 12;
        delay = 0;
        bspeed = 4fx;
        back = 16fx;
    }
    set_invuln(65535);
    set_hurtbox(12fx);       // setHurtbox(24,24)：普通圆形取第一值×0.5
    set_hitbox(8fx);         // setHitbox(16,16)：体碰半径8
    // moveVel(pi/2 + RANDF2*0.34906584, 1.0f)：±20°，1px/帧
    move_vel(0, 90deg + ((rand(7282) - 3641) as angle), 1fx, EASE_LINEAR);
    wait(30);
    // moveVelTime(120, 0, 角哨兵-999999保留, 速4)：只把速度1→4线性插值
    move_speed(120, 4fx, EASE_LINEAR);
    if global(GVAR_RANK) >= RANK_HARD {
        wait(delay);
        var i: int = 0;
        while i < shots {
            // etAim(0,0) 单路自机狙；ANIM a=1 出生退位移 position -= 4*velocity
            var a: angle = aim_player();
            _ = fire(TH16_BALL, 6,
                     $self_x - back * cos(a), $self_y - back * sin(a),
                     bspeed, a, none, none);
            wait(gap);
            i = i + 1;
        }
    }
    loop { wait(1); }
}

// 源 MainSub00：13组×3敌（A从120每轮-20），wait(290)后7组×3敌（A每轮+40）
async sub wave() {
    var a: fx = 120fx;
    wait(OPENING_BUFFER);
    for k in 0..13 {
        _ = spawn_enemy(a - 60fx, -32fx, 60, 0, 1000, 0, girl);
        _ = spawn_enemy(a, -20fx, 60, 0, 1000, 0, girl);
        _ = spawn_enemy(a + 60fx, -8fx, 60, 0, 1000, 0, girl);
        a = a - 20fx;
        wait(15);
    }
    wait(290);
    for j in 0..7 {
        _ = spawn_enemy(a - 60fx, -32fx, 60, 0, 1000, 0, girl);
        _ = spawn_enemy(a, -20fx, 60, 0, 1000, 0, girl);
        _ = spawn_enemy(a + 60fx, -8fx, 60, 0, 1000, 0, girl);
        a = a + 40fx;
        wait(15);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
